/* Shared full-book views and evidence-driven operations. */
function chapterDone(c){return P().done.filter(i=>Math.floor(i/12)===c).length;}
function fullHome(){const next=Math.min(P().done.length,95),c=Math.floor(next/12);return `<div class="hero"><div><p class="eyebrow">CALIFORNIA SCIENCE · GRADE 3</p><h1>A little curiosity.<br>A whole new world.<small>带着好奇心，探索新的科学世界</small></h1><p>Eight chapters. Ninety-six discoveries. Follow the evidence, from living things to light.</p><div class="actions">${btn(P().done.length===96?'Revisit my discoveries →':P().done.length?'Continue my expedition →':'Start my expedition →',`chapter:${c}`,'primary')}</div><p class="subtle" style="margin-top:16px">${P().done.length} / 96 discoveries · 已完成发现</p><div class="progress"><span style="width:${P().done.length/96*100}%"></span></div></div>${image(CHAPTERS[c][3],'','An illustrated research station')}</div><div class="section-head"><h2>Your Expedition Map<small>八章全册探险地图</small></h2><p>Observe → Investigate → Explain<br>观察 · 操作 · 解释</p></div><div class="cards">${CHAPTERS.map((ch,i)=>`<button class="chapter ${i*12<=P().done.length?'live':''}" data-action="chapter:${i}">${image(ch[3])}<div class="body"><span class="number">CHAPTER ${String(i+1).padStart(2,'0')}</span><h3>${ch[0]}<small>${ch[1]}</small></h3><span class="status">${chapterDone(i)}/12 discoveries · ${i*12<=P().done.length?'Explore →':'View trail · 按顺序解锁'}</span></div></button>`).join('')}</div><div class="notice">Every chapter has 12 missions. Complete each mission to unlock the next. Revisit any completed mission whenever you like.<br>每章 12 关，按教材顺序解锁；已完成关卡可随时复习。模型中的示例数据均有标注。</div>`;}
function fullChapter(c){const ch=CHAPTERS[c],ms=MISSIONS.slice(c*12,c*12+12),lessons=[...new Set(ms.map(m=>m.lesson))];return `<div class="breadcrumb">${btn('← Expedition map','home','text-button')}<span>TEXTBOOK pp. ${ch[4]}</span></div><div class="hero"><div><p class="eyebrow">CHAPTER ${String(c+1).padStart(2,'0')} · ${esc(ch[2])}</p><h1>${ch[0]}<small>${ch[1]}</small></h1><p>${['Connect the environment, a feature, and the evidence that it helps.','Explore water conditions and the living things that depend on them.','Follow changes through habitats, populations, and records from the past.','Use models and records to explain patterns in the sky.','Compare objects and observations across our solar system.','Describe, measure, and investigate how matter changes.','Trace energy as it moves and changes in everyday systems.','Follow the path of light, from its source to your eyes.'][c]}</p><span class="tag">12 missions</span><span class="tag">${chapterDone(c)} discoveries saved</span><div class="progress" style="margin-top:20px"><span style="width:${chapterDone(c)/12*100}%"></span></div></div>${image(ch[3])}</div><div class="section-head"><h2>Your Research Trail<small>操作 → 科学推理 → 英语表达</small></h2><p>Saved as you go<br>操作过程自动保存</p></div>${c*12>P().done.length?`<div class="notice">Complete the preceding chapter to begin this trail. 先完成前一章，即可进入本章。${btn('Continue current mission →',`mission:${Math.min(P().done.length,95)}`,'primary')}</div>`:''}${lessons.map(l=>`<p class="lesson-label">${esc(c===0?['Living things and their needs','Life in the desert','Life in the grassland','Life in the forest','Life in the tundra'][l-1]:l)}</p><div class="trail">${ms.map((m,k)=>{const i=c*12+k;return m.lesson!==l?'':`<button class="mission-card" data-action="mission:${i}" ${i>P().done.length?'disabled':''}><span class="index">${P().done.includes(i)?'✓':String(k+1).padStart(2,'0')}</span><span class="copy"><b>${esc(m.title)}</b><small>${esc(m.zh)}</small></span><span class="state">${i>P().done.length?'Locked':P().done.includes(i)?(P().drafts[i]&&!reviewFinished(P().drafts[i],m)?'Continue ↗':'Replay ↗'):'Enter →'}</span></button>`;}).join('')}</div>`).join('')}`;}
function stationArt(i){return i<4?['ch01-habitat-trails','g3-base-desert-grassland-lab','g3-base-forest-field-station','g3-base-habitat-evidence-exhibit'][i]:CHAPTERS[i-3][3];}
function fullBase(){return `<p class="eyebrow">BUILD WITH YOUR DISCOVERIES</p><h1>Your Research Base<small>全册研究基地</small></h1><p>Complete investigations to build a station. Open it to revisit your evidence.<br>通过研究建设设施，打开设施可以复访证据和解释。</p>${STATIONS.map((s,i)=>{return `<section class="panel station">${image(stationArt(i))}<div style="flex:1"><h3>${s[0]}<small>${s[1]}</small></h3><p class="subtle">${Math.min(P().done.length,s[2])}/${s[2]} discoveries along the expedition</p>${btn(P().built.includes(i)?'Open station →':P().done.length>=s[2]?'Build this station +':'Keep exploring to unlock',P().built.includes(i)?`station:${i}`:`construct:${i}`,P().done.length>=s[2]?'primary':'',P().done.length<s[2])}</div></section>`;}).join('')}`;}
function fullStation(i){let start=i<4?[0,2,6,8][i]:(i-3)*12,end=STATIONS[i][2];return `${btn('← Research base','build','text-button')}<div class="station-heading"><h1>${STATIONS[i][0]}<small>${STATIONS[i][1]}</small></h1>${image(stationArt(i))}</div><div class="notes-grid">${MISSIONS.slice(start,end).map((m,k)=>`<article class="panel"><h3>${esc(m.title)}<small>${esc(m.zh)}</small></h3><p>${esc(m.sentence.join(' '))}</p>${help(m.sentenceZh)}${btn('Revisit the evidence →',`mission:${start+k}`)}</article>`).join('')}</div>`;}
function fullComplete(i){const m=MISSIONS[i],end=m.local===12,all=i===95;return `<div class="complete">${image('mascot-celebrate')}<p class="eyebrow">${all?'FULL EXPEDITION COMPLETE':end?'CHAPTER COMPLETE':'DISCOVERY SAVED'} · 发现已保存</p><h1>${all?'Ninety-six discoveries. One curious mind.':end?'A chapter of evidence.':'You followed the evidence.'}<small>${esc(m.zh)} · 完成</small></h1><p>${esc(m.sentence.join(' '))}</p>${all?'<div class="notice">You explored all eight chapters. Revisit your evidence, explain a favorite discovery, and choose a new question to investigate.<br>你已完成八章全部任务。回顾证据、解释最喜欢的发现，再提出一个新问题。</div>':''}<div class="actions" style="justify-content:center">${btn(all?'Visit my research base →':end?'Explore the next chapter →':'Next mission →',all?'build':end?`chapter:${m.chapter}`:`mission:${i+1}`,'primary')}${btn('Back to research trail',`chapter:${m.chapter-1}`)}</div><div class="panel"><h3>A question to keep<small>亲子交流与研究笔记</small></h3><p>${esc(m.parent)}</p><label for="note">My observation or next question · 我的观察或下一个问题</label><textarea id="note" maxlength="3000" data-note="${i}" placeholder="I noticed… / I wonder…">${esc(P().notes[i]||'')}</textarea><p class="subtle">Optional discussion. Notes stay on this device. No recording or automatic oral grading.<br>亲子讨论为可选，笔记保存在本机，不录音、不自动评分。</p>${btn('Save note','savenote')}</div></div>`;}
function fullPlan(){const done=P().done,correct=Object.values(P().first).filter(Boolean).length,due=done.filter(i=>Date.now()-(P().review[i]||0)>86400000);return `<p class="eyebrow">GROW AT YOUR OWN PACE</p><h1>My Learning<small>全册学习与复习</small></h1><div class="stats"><div class="stat"><strong>${done.length}/96</strong><small>Discoveries · 已完成</small></div><div class="stat"><strong>${correct}/${Object.keys(P().first).length}</strong><small>First evidence answers · 首答正确</small></div><div class="stat"><strong>${P().built.length}/${STATIONS.length}</strong><small>Research stations · 已建设施</small></div></div><div class="panel"><h2>One connected learning journey<small>跨章节螺旋复习</small></h2>${CHAPTERS.map((c,i)=>`<div class="chapter-progress"><div><b>${i+1}. ${c[0]}</b><small>${c[1]} · ${chapterDone(i)}/12</small></div>${btn(chapterDone(i)===12?'Review →':'Open trail →',`chapter:${i}`)}</div>`).join('')}</div><section class="panel" style="margin-top:20px"><h2>A little review goes a long way.<small>隔天再用一次证据</small></h2><p class="subtle">Tasks completed at least a day ago become review candidates. Replays do not duplicate rewards.<br>完成至少一天后进入复习候选；重复游玩不重复奖励。</p><div class="actions">${(due.length?due.slice(0,4):done.slice(-3)).map(i=>btn(MISSIONS[i].title,`mission:${i}`)).join('')||btn('Begin mission 1 →','mission:0','primary')}</div></section><section class="panel" style="margin-top:20px"><h2>Your progress stays here.<small>本机存档与备份</small></h2><p>Child and parent have separate records. Download a backup before clearing browser data.<br>亲子档案独立；清理浏览器数据前请导出备份。</p><div class="actions">${btn('Export backup ↓','export')}<label class="file-label">Import backup ↑<input type="file" id="import" accept="application/json,.json"></label></div><p class="subtle">Import replaces both local G3 profiles. Earlier chapter-one backups are supported. G2 remains independent.<br>导入替换两个 G3 本机档案，兼容第一章旧备份；G2 独立保存。</p></section><p class="subtle" style="margin-top:20px">Original companion activities aligned to California Science Grade 3 (2008), Chapters 1–8. Not the publisher's official website. AI narration: Kokoro-82M, Apache-2.0.<br>依据旧版教材编写的原创伴学活动，非出版社官方网站。</p>`;}
function sequenceUI(m,d){const items=m.sequence||m.extraSequence;return `<p class="subtle">Tap the cards in order. 依据线索按顺序点选。</p><div class="sentence-answer">${d.path.map((j,k)=>`<span class="badge">${k+1}. ${esc(items[j])}</span>`).join('')||'<span class="subtle">Build your sequence here · 在这里建立顺序</span>'}</div><div class="path-bank">${items.map((_,j)=>(j+Math.ceil(items.length/2))%items.length).map(j=>btn(esc(items[j]),`seq:${j}`,'',d.path.includes(j))).join('')}${btn('Reset sequence','resetseq','text-button')}</div>`;}
function experimentUI(m,d){let x=m.experiment,ready=d.prediction!==null;return `<div class="notice"><b>Change · 改变：</b>${esc(x.variable)}<br><b>Keep the same · 保持：</b>${esc(x.controls)}</div><p class="subtle">1. Save a prediction. Predictions are not marked right or wrong.<br>先保存预测，预测本身不计对错。</p><div class="options">${x.prediction.map((s,j)=>btn(esc(s),`predict:${j}`,d.prediction===j?'selected':'',d.seen.length>0)).join('')}</div><p class="subtle">2. Set the condition, run the model, then compare records.<br>选择条件、运行模型，并比较记录。</p><div class="model-tabs">${x.states.map((s,j)=>btn(`${d.seen.includes(j)?'✓ ':''}${esc(s.label)}`,`xmode:${j}`,d.mode===j?'selected':'',!ready)).join('')}</div>${ready?`<div class="model-stage">${drawExperiment(m,d)}<p class="model-label">TEACHING MODEL · 简化教学模型 · NOT TO SCALE</p>${btn(d.seen.includes(d.mode)?'Run again ↻':'Run and record →','xrun','primary')}<div class="record" aria-live="polite">${d.seen.includes(d.mode)?esc(x.states[d.mode].reading):'Run to collect this observation. 运行后收集本次观察。'}</div></div>`:'<div class="notice">Make a prediction to open the investigation. 先预测，再开始研究。</div>'}<table class="data-table"><caption>My evidence log · 我的模型记录（示例）</caption><thead><tr><th>Condition 条件</th><th>Observation 观察</th></tr></thead><tbody>${x.states.map((s,j)=>`<tr><td>${esc(s.label)}</td><td>${d.seen.includes(j)?esc(s.reading):'Not recorded · 未记录'}</td></tr>`).join('')}</tbody></table><p class="subtle">${d.seen.length}/${x.states.length} conditions recorded · 每种条件都需要运行并记录</p>`;}
function fullOperation(m,d){let body='';if(m.kind==='match')body=matching(m,d);if(m.kind==='sort')body=`<div class="sort-grid">${m.items.map((x,j)=>`<div class="sort-item"><b>${esc(x[0])}</b>${m.groups.map((g,k)=>btn(esc(g),`sort:${j}:${k}`,d.sort[j]===k?'selected':'')).join('')}</div>`).join('')}</div>`;if(m.kind==='sequence')body=sequenceUI(m,d);if(m.kind==='experiment')body=experimentUI(m,d);if(m.extraSequence)body+=`<h3>Connect the steps<small>串起过程</small></h3>${sequenceUI(m,d)}`;if(m.extraPairs)body+=`<h3>Connect the evidence<small>匹配证据</small></h3>${matching({pairs:m.extraPairs},d)}`;return `<p class="instruction">${esc(m.instruction)}</p>${help(m.instructionZh)}${bar(active,'operation')}${body}${d.opOK?`<div class="result"><b>Evidence collected ✓</b><p>${esc(m.evidenceEn||m.feedback)}</p>${help(m.evidenceZh||m.feedbackZh)}</div>`:''}<div aria-live="polite">${flash?`<div class="result ${bad?'error':''}">${esc(flash)}</div>`:''}</div><div class="task-footer"><span class="subtle">Use observations to support your answer.<br>先完成操作，再用观察支持答案。</span>${btn(d.opOK?'Use the evidence →':'Check my investigation',d.opOK?'next':'checkop','primary')}</div>`;}
function fullOpComplete(m,d){let main=m.kind==='match'?d.pairs.length===m.pairs.length:m.kind==='sort'?m.items.every((x,j)=>d.sort[j]===x[1]):m.kind==='sequence'?d.path.join()===m.sequence.map((_,j)=>j).join():m.kind==='experiment'?d.seen.length===m.experiment.states.length:false;return main&&(!m.extraSequence||d.path.join()===m.extraSequence.map((_,j)=>j).join())&&(!m.extraPairs||d.pairs.length===m.extraPairs.length);}
function fullDiscover(chapter){let c=Number.isInteger(chapter)&&chapter>=0&&chapter<8?chapter:Math.floor(Math.max(0,P().done.length-1)/12),ids=P().done.filter(i=>Math.floor(i/12)===c);return `<p class="eyebrow">YOUR COLLECTED WORDS & EVIDENCE</p><h1>Field Notes<small>全册发现手册</small></h1><div class="chapter-tabs" aria-label="Choose chapter">${CHAPTERS.map((ch,j)=>`<a class="${j===c?'selected':''}" href="#discover/${j}">${j+1}. ${ch[0]}<small>${ch[1]} · ${chapterDone(j)}/12</small></a>`).join('')}</div><h2>${CHAPTERS[c][0]}<small>${CHAPTERS[c][1]}</small></h2>${ids.length?`<div class="notes-grid">${ids.map(i=>{const m=MISSIONS[i];return `<article class="panel"><span class="tag">DISCOVERY ${m.local}</span><h3>${esc(m.word[0])}<small>${esc(m.word[1])}</small></h3>${bar(i,'word')}<p>${esc(m.sentence.join(' '))}</p>${help(m.sentenceZh)}${P().notes[i]?`<blockquote>${esc(P().notes[i])}</blockquote>`:''}${btn('Open discovery',`complete:${i}`)}</article>`;}).join('')}</div>`:`<div class="notice">Complete this chapter's missions to collect evidence and explanations.<br>完成本章关卡后，证据与解释会保存在这里。</div>${btn('Open research trail →',`chapter:${c}`,'primary')}`}`;}
function drawExperiment(m,d){const x=m.experiment,s=x.states[d.mode],n=d.mode,count=x.states.length,model=x.model||'',v=s.value;let body='';const text=(xx,yy,t,size=14)=>`<text x="${xx}" y="${yy}" font-size="${size}" fill="#234838">${esc(t)}</text>`;const line=(x1,y1,x2,y2,color='#d5ad49',width=4)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}"/>`;
 if(typeof drawPhysicalModel==='function')body=drawPhysicalModel(m,d)||'';
 if(!body&&m.chapter===2&&m.local===2){const y=55+n*65;body=`<defs><linearGradient id="water-depth" x2="0" y2="1"><stop stop-color="#acdce3"/><stop offset="1" stop-color="#284b65"/></linearGradient></defs><rect x="80" y="35" width="360" height="200" rx="10" fill="url(#water-depth)"/>${line(260,25,260,y,'#667e7d',2)}<circle cx="260" cy="${y}" r="12" fill="#e9bd59"/>${text(105,65,'Surface',13)}${text(285,y+5,String(v??[90,35,2][n])+' units',16)}`;}
 if(!body&&m.chapter===2&&m.local===7){body=`<path d="M100 35V220H420V35" fill="#bddfe6" stroke="#709ba4" stroke-width="3"/><line x1="100" y1="80" x2="420" y2="80" stroke="#68a6b1"/><circle cx="260" cy="${n?82:200}" r="17" fill="#c39d5a"/>${text(140,55,n?'Saltier water':'Fresh water')}`;}
 if(!body&&m.chapter===4&&[2,3].includes(m.local)){let angle=n/count*Math.PI*2,px=285+65*Math.cos(angle),py=130+65*Math.sin(angle);body=`<circle cx="70" cy="130" r="30" fill="#e5bc56"/>${[90,130,170].map(y=>line(110,y,195,y)).join('')}<circle cx="285" cy="130" r="75" fill="#2e5770"/><path d="M285 55A75 75 0 0 0 285 205Z" fill="#88c3ca"/><circle cx="${px}" cy="${py}" r="8" fill="#e4bd57"/>${text(230,235,'Observer on rotating Earth',13)}`;}
 if(!body&&m.chapter===4&&[8,9,11].includes(m.local)){let lit=s.illuminatedFraction??[0,.25,.5,.75,1][Math.min(n,4)];body=`<circle cx="260" cy="125" r="75" fill="#314c5f"/><clipPath id="moon-disk"><circle cx="260" cy="125" r="75"/></clipPath><rect x="${335-150*lit}" y="50" width="150" height="150" fill="#e9e3bc" clip-path="url(#moon-disk)"/>${text(120,235,'Observer view · simplified phase symbol',13)}`;}
 if(!body&&m.chapter===5&&m.local===4){const a=n/count*Math.PI*2,px=260+150*Math.cos(a),py=125+80*Math.sin(a);body=`<ellipse cx="260" cy="125" rx="150" ry="80" fill="none" stroke="#b7c5ad" stroke-dasharray="5 5"/><circle cx="260" cy="125" r="23" fill="#e9bc54"/><circle cx="${px}" cy="${py}" r="15" fill="#6aabb9"/>${text(170,245,'Orbit around the Sun',14)}`;}
 if(!body&&Number.isFinite(v)){const max=Math.max(...x.states.map(t=>Math.abs(t.value||0)),1),w=Math.max(1,Math.abs(v)/max*360);body=`${line(70,205,460,205,'#adbda8',2)}<rect x="70" y="85" width="${w}" height="90" rx="8" fill="#7ea575"/>${text(75,65,`${v} ${x.unit||'relative units'}`,22)}${text(75,238,'Example model reading · 示例模型读数',13)}`;}
 if(!body){body=`<circle cx="115" cy="120" r="48" fill="#e4e8d7"/><circle cx="405" cy="120" r="48" fill="#cee1d1"/>${line(174,120,342,120,'#8baf98',4)}<path d="M330 110l15 10-15 10" fill="none" stroke="#8baf98" stroke-width="4"/>${text(89,126,'Input',16)}${text(374,126,'Observe',14)}${text(200,85,`Trial ${n+1}`,20)}${text(105,218,'Compare the observation record below.',14)}`;}
 return `<svg class="scene" viewBox="0 0 520 260" role="img" aria-label="${esc(m.title+' — '+s.label)}"><title>${esc(m.title+' — '+s.label)}</title>${body}</svg>`;}
